  source_sha: {description: Exact source commit, required: true, type: string}\npermissions:\n  contents: read\nconcurrency:\n  group: mobile-builder-${{ inputs.project_id }}-${{ inputs.request_id }}\n  cancel-in-progress: false\nenv:\n  PROJECT_ID: ${{ inputs.project_id }}\n  PLATFORM: ${{ inputs.platform }}\n  REQUEST_ID: ${{ inputs.request_id }}\n  SOURCE_SHA: ${{ inputs.source_sha }}\njobs:\n  readiness:\n    name: Check signing readiness\n    runs-on: ubuntu-latest\n    timeout-minutes: 5\n    outputs:\n      android: ${{ steps.check.outputs.android }}\n      ios: ${{ steps.check.outputs.ios }}\n    steps:\n      - uses: actions/checkout@v4\n        with: {ref: '${{ inputs.source_sha }}', persist-credentials: false}\n      - id: check\n        run: python3 .builder/build.py readiness\n        env:\n          HAS_ANDROID_KEYSTORE_BASE64: ${{ secrets.ANDROID_KEYSTORE_BASE64 != '' }}\n          HAS_ANDROID_KEYSTORE_PASSWORD: ${{ secrets.ANDROID_KEYSTORE_PASSWORD != '' }}\n          HAS_ANDROID_KEY_ALIAS: ${{ secrets.ANDROID_KEY_ALIAS != '' }}\n          HAS_ANDROID_KEY_PASSWORD: ${{ secrets.ANDROID_KEY_PASSWORD != '' }}\n          HAS_APPLE_CERTIFICATE_P12_BASE64: ${{ secrets.APPLE_CERTIFICATE_P12_BASE64 != '' }}\n          HAS_APPLE_CERTIFICATE_PASSWORD: ${{ secrets.APPLE_CERTIFICATE_PASSWORD != '' }}\n          HAS_APPLE_PROVISIONING_PROFILE_BASE64: ${{ secrets.APPLE_PROVISIONING_PROFILE_BASE64 != '' }}\n          HAS_APPLE_TEAM_ID: ${{ secrets.APPLE_TEAM_ID != '' }}\n      - uses: actions/upload-artifact@v4\n        with:\n          name: Build-Readiness-${{ inputs.request_id }}\n          path: readiness/Build-Readiness.json\n          retention-days: 14\n  android:\n    name: Android signed APK\n    needs: readiness\n    if: needs.readiness.outputs.android == 'true'\n    runs-on: ubuntu-latest\n    timeout-minutes: 30\n    steps:\n      - uses: actions/checkout@v4\n        with: {ref: '${{ inputs.source_sha }}', persist-credentials: false}\n      - uses: acti